const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Denmark geometry
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const denmark = countries.filter(ee.Filter.eq('ADM0_NAME', 'Denmark'));
  const geometry = denmark.geometry();

  // 2. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Get Sentinel-2 data for 2017
  const date2017 = ee.Date('2017-07-19');
  let col2017 = ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(geometry)
      .filterDate(date2017.advance(-5, 'day'), date2017.advance(5, 'day'))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
      .map(maskS2clouds);

  const size2017 = col2017.size().getInfo();
  console.log('2017 Images:', size2017);

  if (size2017 === 0) {
    console.log('No data for July 2017.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get Sentinel-2 data for 2018
  const date2018 = ee.Date('2018-07-24');
  let col2018 = ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(geometry)
      .filterDate(date2018.advance(-5, 'day'), date2018.advance(5, 'day'))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
      .map(maskS2clouds);

  const size2018 = col2018.size().getInfo();
  console.log('2018 Images:', size2018);

  if (size2018 === 0) {
    console.log('No data for July 2018.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Create median composites and calculate brownness index
  const img2017 = col2017.median().clip(geometry);
  const img2018 = col2018.median().clip(geometry);

  // Brownness index: Red/NIR ratio (higher = more brown/less vegetation)
  const brown2017 = img2017.select('B4').divide(img2017.select('B8'));
  const brown2018 = img2018.select('B4').divide(img2018.select('B8'));

  // 6. Check valid pixel counts
  const count2017 = brown2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).get('B4').getInfo();

  const count2018 = brown2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).get('B4').getInfo();

  console.log('Valid pixels 2017:', count2017);
  console.log('Valid pixels 2018:', count2018);

  if (count2017 === 0 || count2018 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Calculate mean brownness for both years
  const brown2017Mean = brown2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).get('B4').getInfo();

  const brown2018Mean = brown2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9
  }).get('B4').getInfo();

  console.log('2017 Brownness (Red/NIR):', brown2017Mean.toFixed(4));
  console.log('2018 Brownness (Red/NIR):', brown2018Mean.toFixed(4));

  // 8. Validation and final answer
  if (brown2017Mean === null || brown2018Mean === null || 
      isNaN(brown2017Mean) || isNaN(brown2018Mean)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  const diff = brown2018Mean - brown2017Mean;
  console.log('Difference (2018-2017):', diff.toFixed(4));

  if (brown2018Mean > brown2017Mean) {
    console.log('2018 was browner than 2017.');
    console.log('<answer>A</answer>');
  } else {
    console.log('2018 was not browner than 2017.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
